import contentstack from 'contentstack';
import ContentstackLivePreview from '@contentstack/live-preview-utils';

export type StackOptions = {
  apiKey: string;
  deliveryToken: string;
  environment: string;
  region?: string;
  host?: string;
};

export class Stack {
  private stack: contentstack.Stack;

  constructor(options: StackOptions) {
    const stackOptions: any = {
      api_key: options.apiKey,
      delivery_token: options.deliveryToken,
      environment: options.environment,
    };

    if (options.region) {
      stackOptions.region = options.region;
    }

    if (options.host) {
      stackOptions.host = options.host;
    }

    this.stack = contentstack.Stack(stackOptions);

    ContentstackLivePreview.init({
      stackSdk: this.stack,
    });
  }

  async getEntry(contentType: string, entryUid: string, locale?: string) {
    const query = this.stack.ContentType(contentType).Entry(entryUid);

    if (locale) {
      query.language(locale);
    }

    const result = await query.includeReference().toJSON().fetch();

    if (ContentstackLivePreview.isLivePreviewEnabled()) {
      const livePreviewData = ContentstackLivePreview.getLivePreviewData(result);
      return livePreviewData;
    }

    return result;
  }
}
</tool_result>

